<template>
	<!-- Keputusan Ketua atas hari sakit sesudah Batas Hari Sakit, di Penyesuaian:
	     bertanggal akhir -> bagi angka (potong cuti tahunan / tanpa upah);
	     tanpa tanggal akhir -> pilih aturan. -->
	<Teleport to="body">
		<Transition
			enter-active-class="transition-opacity duration-200"
			enter-from-class="opacity-0"
			leave-active-class="transition-opacity duration-150"
			leave-to-class="opacity-0"
		>
			<div
				v-if="open"
				class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40 sm:items-center"
				@click.self="batal"
			>
				<div
					class="max-h-[92vh] w-full max-w-md overflow-y-auto rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl sm:rounded-3xl"
				>
					<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300 sm:hidden" />
					<h2 class="text-center text-base font-semibold text-ui-ink-gray-900">
						{{
							terbuka
								? 'Keputusan Hari Lewat Batas'
								: `Bagi ${angka(hari)} Hari Lewat Batas`
						}}
					</h2>
					<p class="mt-1 text-center text-xs text-ui-ink-gray-500">
						<template v-if="terbuka">
							Sakit belum ada tanggal akhirnya. Saat ini {{ angka(hari) }} hari kerja lewat
							batas {{ batas }} hari dan terus bertambah sampai karyawan scan masuk.
							Karyawan akan diminta menyetujui.
						</template>
						<template v-else>
							{{ angka(hari) }} hari kerja lewat batas {{ batas }} hari. Kehadiran tetap
							Sakit. Karyawan akan diminta menyetujui.
						</template>
					</p>

					<!-- Tanpa tanggal akhir: pilih aturan. -->
					<div v-if="terbuka" class="mt-4 space-y-2.5">
						<button
							v-for="opsi in OPSI_ATURAN"
							:key="opsi.value"
							type="button"
							class="flex w-full items-start gap-3 rounded-2xl border px-3 py-3 text-left transition"
							:class="
								aturan === opsi.value
									? 'border-primary/40 bg-ui-surface-blue-50'
									: 'border-ui-line-gray-100 bg-ui-surface active:bg-ui-surface-gray-50'
							"
							@click="aturan = opsi.value"
						>
							<span
								class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2"
								:class="aturan === opsi.value ? 'border-primary' : 'border-ui-line-gray-300'"
							>
								<span v-if="aturan === opsi.value" class="h-2.5 w-2.5 rounded-full bg-primary"></span>
							</span>
							<span class="min-w-0 flex-1">
								<span class="block text-sm font-semibold text-ui-ink-gray-900">{{
									opsi.label
								}}</span>
								<span class="mt-0.5 block text-xs text-ui-ink-gray-500">{{
									opsi.value === 'Potong Cuti Tahunan'
										? `Saldo ${angka(saldoTahunan)} hari. Jika habis, sisanya tanpa upah.`
										: 'Semua hari setelah batas tanpa upah.'
								}}</span>
								<span v-if="aturan === opsi.value" class="mt-1 block text-xs font-medium text-primary"
									>Saat ini: {{ ringkasAturan(opsi.value) }}</span
								>
							</span>
						</button>
					</div>

					<!-- Bertanggal akhir: bagi angka. -->
					<template v-else>
						<div class="mt-4 space-y-2.5">
							<div
								v-for="opsi in OPSI"
								:key="opsi.key"
								class="flex items-center gap-3 rounded-2xl border border-ui-line-gray-100 px-3 py-2.5"
								:class="nilai[opsi.key] ? 'bg-ui-surface-blue-50' : 'bg-ui-surface'"
							>
								<span class="h-2.5 w-2.5 shrink-0 rounded-full" :class="opsi.titik"></span>
								<span class="min-w-0 flex-1">
									<span class="block text-sm font-semibold text-ui-ink-gray-900">{{
										opsi.label
									}}</span>
									<span class="block text-xs text-ui-ink-gray-500">{{
										opsi.key === 'sakit_potong_tahunan'
											? `Saldo ${angka(saldoTahunan)} hari`
											: opsi.ket
									}}</span>
								</span>
								<div class="flex shrink-0 items-center gap-1">
									<button
										type="button"
										class="flex h-8 w-8 items-center justify-center rounded-full border border-ui-line-gray-200 text-lg leading-none text-ui-ink-gray-600 active:bg-ui-surface-gray-100 disabled:opacity-30"
										:disabled="nilai[opsi.key] <= 0"
										@click="ubah(opsi.key, -1)"
									>
										−
									</button>
									<input
										v-model.number="nilai[opsi.key]"
										type="number"
										min="0"
										step="0.5"
										inputmode="decimal"
										class="w-12 rounded-lg border-0 bg-transparent p-0 text-center text-base font-semibold text-ui-ink-gray-900 focus:ring-0"
									/>
									<button
										type="button"
										class="flex h-8 w-8 items-center justify-center rounded-full border border-ui-line-gray-200 text-lg leading-none text-ui-ink-gray-600 active:bg-ui-surface-gray-100 disabled:opacity-30"
										:disabled="!bisaTambah(opsi.key)"
										@click="ubah(opsi.key, 1)"
									>
										+
									</button>
								</div>
							</div>
						</div>
						<p
							class="mt-3 rounded-xl px-3 py-2 text-xs"
							:class="
								galat
									? 'bg-ui-surface-red-50 text-ui-ink-red-600'
									: 'bg-ui-surface-gray-50 text-ui-ink-gray-500'
							"
						>
							{{ galat || `Terbagi ${angka(total)} dari ${angka(hari)} hari.` }}
						</p>
					</template>

					<div class="mt-4 flex gap-2">
						<button
							type="button"
							class="flex-1 rounded-full border border-ui-line-gray-200 py-3 text-sm font-semibold text-ui-ink-gray-600"
							:disabled="memproses"
							@click="batal"
						>
							Batal
						</button>
						<button
							type="button"
							class="flex-1 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary disabled:opacity-50"
							:disabled="(terbuka ? !aturan : !!galat) || memproses"
							@click="simpan"
						>
							{{ memproses ? 'Memproses…' : 'Setujui' }}
						</button>
					</div>
				</div>
			</div>
		</Transition>
	</Teleport>
</template>

<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { angka } from '../data/cutiStatus'

const props = defineProps({
	open: { type: Boolean, default: false },
	hari: { type: Number, default: 0 },
	batas: { type: Number, default: 14 },
	saldoTahunan: { type: Number, default: 0 },
	// Penyesuaian tanpa tanggal akhir: Ketua memilih aturan, bukan angka.
	terbuka: { type: Boolean, default: false },
	memproses: { type: Boolean, default: false },
})
const emit = defineEmits(['simpan', 'batal'])

const OPSI = [
	{
		key: 'sakit_potong_tahunan',
		label: 'Potong cuti tahunan',
		ket: '',
		titik: 'bg-ui-surface-amber-400',
	},
	{
		key: 'sakit_non_pay',
		label: 'Tanpa upah',
		ket: 'Hari paling akhir ditandai tanpa upah',
		titik: 'bg-ui-surface-red-400',
	},
]
const OPSI_ATURAN = [
	{ value: 'Potong Cuti Tahunan', label: 'Potong cuti tahunan' },
	{ value: 'Tanpa Upah', label: 'Tanpa upah' },
]

const nilai = reactive({ sakit_potong_tahunan: 0, sakit_non_pay: 0 })
const aturan = ref('Potong Cuti Tahunan')

// Tiap kali dibuka: potong saldo sebanyak yang ada, sisanya tanpa upah —
// Ketua tinggal menggeser.
watch(
	() => props.open,
	(buka) => {
		if (!buka) return
		const potong = Math.min(props.hari, props.saldoTahunan)
		nilai.sakit_potong_tahunan = potong
		nilai.sakit_non_pay = props.hari - potong
		aturan.value = 'Potong Cuti Tahunan'
	}
)

function ringkasAturan(a) {
	const potong = a === 'Potong Cuti Tahunan' ? Math.min(props.hari, props.saldoTahunan) : 0
	const bagian = []
	if (potong) bagian.push(`${angka(potong)} hari potong cuti`)
	if (props.hari - potong) bagian.push(`${angka(props.hari - potong)} hari tanpa upah`)
	return bagian.join(' · ') || '—'
}

const total = computed(
	() => Number(nilai.sakit_potong_tahunan || 0) + Number(nilai.sakit_non_pay || 0)
)
const sisa = computed(() => props.hari - total.value)
const lain = (key) => (key === 'sakit_potong_tahunan' ? 'sakit_non_pay' : 'sakit_potong_tahunan')

function bisaTambah(key) {
	if (key === 'sakit_potong_tahunan' && Number(nilai[key] || 0) + 1 > props.saldoTahunan + 0.001)
		return false
	return sisa.value >= 1 || Number(nilai[lain(key)] || 0) >= 1
}

// Menambah satu pilihan saat total sudah penuh mengambil dari pilihan lainnya.
function ubah(key, arah) {
	if (arah > 0) {
		if (!bisaTambah(key)) return
		if (sisa.value < 1) nilai[lain(key)] -= 1
		nilai[key] = Number(nilai[key] || 0) + 1
	} else {
		nilai[key] = Math.max(0, Number(nilai[key] || 0) - 1)
	}
}

const galat = computed(() => {
	if (Number(nilai.sakit_potong_tahunan || 0) < 0 || Number(nilai.sakit_non_pay || 0) < 0)
		return 'Jumlah hari tidak boleh negatif.'
	if (Number(nilai.sakit_potong_tahunan || 0) > props.saldoTahunan + 0.001)
		return `Saldo cuti tahunan tinggal ${angka(props.saldoTahunan)} hari.`
	if (Math.abs(sisa.value) > 0.001)
		return `Jumlahnya harus ${angka(props.hari)} hari, sekarang ${angka(total.value)} hari.`
	return ''
})

function simpan() {
	emit('simpan', props.terbuka ? { aturan_di_atas_batas: aturan.value } : { ...nilai })
}

function batal() {
	if (props.memproses) return
	emit('batal')
}
</script>
